import json, os, collections, datetime
D='/tmp/export'
def load(t):
    return [json.loads(l) for l in open(os.path.join(D,t+'.ndjson'))]
res={t:load(t) for t in ['AllergyIntolerance','Basic','Condition','DocumentReference','EpisodeOfCare','MedicationAdministration','MedicationDispense','Observation','Patient','Specimen','Task']}
byid={}
for t,rs in res.items():
    for r in rs: byid[r['id']]=r
def ext(r,name,default=None):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k,v in e.items():
                if k.startswith('value'): return v
    return default
def subj(r):
    for k in ('subject','patient','for'):
        if k in r and isinstance(r[k],dict) and 'reference' in r[k]:
            return r[k]['reference'].split('/')[-1]
    return None
def et(r):
    return ext(r,'event-time') or r.get('date') or r.get('created') or ''
bypat=collections.defaultdict(list)
for t,rs in res.items():
    for r in rs:
        if t=='Patient': bypat[r['id']].append(r)
        else:
            s=subj(r)
            if s: bypat[s].append(r)
acc_by_num=collections.defaultdict(list)
for b in res['Basic']:
    acc_by_num[ext(b,'accession')].append(b)
spec_by_id={s['id']:s for s in res['Specimen']}
pat_by_id={p['id']:p for p in res['Patient']}
def mrn(p):
    return p['identifier'][0]['value']
pat_by_mrn={}
for p in res['Patient']: pat_by_mrn.setdefault(mrn(p),[]).append(p)
