def ext(r,name,default=None):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            for k,v in e.items():
                if k.startswith('value'): return v
    return default
def subj(r):
    for k in ('subject','patient','for'):
        if k in r and isinstance(r[k],dict) and 'reference' in r[k]:
            return r[k]['reference'].split('/')[-1]
    return None
def et(r):
    return ext(r,'event-time') or r.get('date') or r.get('created') or ''
